// record_demo.js — drive the published demo through the storyboard and record it.
//
//   node record_demo.js                 # full run, writes recording/ + beat_times.json
//   node record_demo.js --to B08        # rehearsal: stop after beat B08
//   node record_demo.js --speed 4       # rehearsal at 4x (timings are NOT usable for captions)
//
// The beats and their planned start times come from `beats.json` (generated by
// build_video.py from the storyboard). Every beat records the second it actually started
// into `beat_times.json`; feeding that back through
//     python build_video.py --anchors beat_times.json
// re-times the subtitles onto the real recording, so drift cannot desynchronise them.
//
// Two deliberate choices:
//   * the access PIN is seeded into sessionStorage before the app boots, so the gate never
//     appears and the code is never filmed;
//   * a synthetic cursor is drawn by an injected script, because Playwright's recorder does
//     not capture the real pointer — without it every click would look like magic.

const fs = require('fs');
const path = require('path');
const { chromium } = require('D:/mailbot/node_modules/playwright-core');

const HERE = __dirname;
const URL = 'https://dr-classification.pages.dev/';
const PIN = fs.readFileSync('D:/dissertation-project/demo/.demo-password', 'utf8').trim();
const IMG = path.join(HERE, 'patient_294');
const OUT = path.join(HERE, 'recording');
const ZOOM = 1.4;

const args = process.argv.slice(2);
const argOf = (name, fallback) => {
  const i = args.indexOf(name);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const STOP_AFTER = argOf('--to', null);
const SPEED = Number(argOf('--speed', 1));

// ── injected page helpers ───────────────────────────────────────────────────
const CURSOR_SCRIPT = () => {
  const install = () => {
    if (document.getElementById('__cursor')) return;
    const dot = document.createElement('div');
    dot.id = '__cursor';
    dot.style.cssText = [
      'position:fixed', 'left:0', 'top:0', 'width:22px', 'height:22px',
      'margin:-11px 0 0 -11px', 'border-radius:50%',
      'background:rgba(29,158,117,0.35)', 'border:2px solid rgba(20,90,70,0.9)',
      'box-shadow:0 0 6px rgba(0,0,0,0.35)', 'pointer-events:none', 'z-index:2147483647',
      'transition:transform 90ms ease-out',
    ].join(';');
    document.body.appendChild(dot);
    const move = (e) => {
      dot.style.transform = `translate(${e.clientX}px, ${e.clientY}px)`;
    };
    document.addEventListener('mousemove', move, true);
    document.addEventListener('mousedown', () => { dot.style.width = '14px'; dot.style.height = '14px'; }, true);
    document.addEventListener('mouseup', () => { dot.style.width = '22px'; dot.style.height = '22px'; }, true);
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', install);
  else install();
};

// ── timing ──────────────────────────────────────────────────────────────────
let t0 = 0;
const now = () => (Date.now() - t0) / 1000;
const sleep = (s) => new Promise((r) => setTimeout(r, Math.max(0, (s * 1000) / SPEED)));
async function waitUntil(sec) {
  const target = sec / SPEED;
  const gap = target - now();
  if (gap > 0) await new Promise((r) => setTimeout(r, gap * 1000));
}

// ── interaction helpers (all pointer-driven, so the cursor is visible) ───────
async function moveTo(page, locator, { steps = 14 } = {}) {
  // The pointer API does not scroll for us the way locator.click() does, so an element
  // below the fold would be "clicked" outside the viewport and nothing would happen.
  await locator.scrollIntoViewIfNeeded({ timeout: 5000 }).catch(() => {});
  const box = await locator.boundingBox();
  if (!box) throw new Error('element has no box');
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2, { steps });
  return box;
}

async function click(page, locator) {
  await moveTo(page, locator);
  await sleep(0.18);
  await page.mouse.down();
  await sleep(0.09);
  await page.mouse.up();
}

function byText(page, text, { scope = 'button', last = false } = {}) {
  const loc = page.locator(scope, { hasText: text });
  return last ? loc.last() : loc.first();
}

async function scrollToText(page, text, block = 'center') {
  await page.evaluate(([needle, blk]) => {
    const walk = document.evaluate(
      `//*[not(self::script)][contains(normalize-space(text()), ${JSON.stringify(needle)})]`,
      document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
    (walk || document.body).scrollIntoView({ behavior: 'smooth', block: blk });
  }, [text, block]);
}

async function scrollBy(page, dy, chunks = 12) {
  for (let i = 0; i < chunks; i++) {
    await page.mouse.wheel(0, dy / chunks);
    await sleep(0.05);
  }
}

const nextSlide = (page) => byText(page, '→');
const prevSlide = (page) => byText(page, '←');

async function stepForward(page, times = 1, dwell = 0.9) {
  for (let i = 0; i < times; i++) { await click(page, nextSlide(page)); await sleep(dwell); }
}
async function stepBack(page, times = 1, dwell = 0.9) {
  for (let i = 0; i < times; i++) { await click(page, prevSlide(page)); await sleep(dwell); }
}

async function slideLabel(page) {
  return page.evaluate(() => {
    const t = document.body.innerText;
    const i = t.indexOf('Preprocessing stages');
    return t.slice(i, i + 120).split('\n').filter(Boolean).slice(0, 5).join(' | ');
  });
}

async function navTo(page, label) {
  await click(page, page.locator('nav button', { hasText: label }).first());
}

// ── the beats ───────────────────────────────────────────────────────────────
// Each entry is the action performed at the START of that beat; the rest of the beat is
