    await stepForward(page, 1);
    await sleep(2.5);
    const heat = byText(page, 'probability heatmap');
    if (await heat.count()) {
      await click(page, heat);
      await sleep(3.0);
      await click(page, byText(page, 'probability heatmap'));
    }
