(async () => {
  const beats = JSON.parse(fs.readFileSync(path.join(HERE, 'beats.json'), 'utf8'));
  fs.mkdirSync(OUT, { recursive: true });

  const browser = await chromium.launch({ channel: 'chrome', headless: false });
  const ctx = await browser.newContext({
    viewport: { width: 1920, height: 1080 },
    recordVideo: { dir: OUT, size: { width: 1920, height: 1080 } },
  });
  await ctx.addInitScript((pin) => {
    try { sessionStorage.setItem('demo_password', pin); } catch (e) { /* ignore */ }
    try { localStorage.setItem('viewMode', 'lite'); } catch (e) { /* ignore */ }
  }, PIN);
  await ctx.addInitScript(CURSOR_SCRIPT);

  const page = await ctx.newPage();
  const videoStartedAt = Date.now();          // the recorder starts with the page
  await page.goto(URL, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForTimeout(6000);
  await page.evaluate((z) => { document.documentElement.style.zoom = String(z); }, ZOOM);
  await page.waitForTimeout(2500);
  if (await page.locator('input[aria-label="Access code"]').count()) {
    throw new Error('the access gate is showing — the PIN would be filmed; aborting');
  }

  const times = {};
  t0 = Date.now();
  // Everything before this instant (load, zoom, gate check) is lead-in that has to be
  // trimmed off the front of the file before the captions line up.
  times._offset = Number(((t0 - videoStartedAt) / 1000).toFixed(2));
  console.log(`lead-in before beat 0: ${times._offset}s (trim this off the recording)`);
  for (const beat of beats) {
    await waitUntil(beat.start);
    times[beat.id] = Number(now().toFixed(2));
    console.log(`${times[beat.id].toFixed(1).padStart(6)}s  ${beat.id}  ${beat.title}  (planned ${beat.start}s)`);
    const action = ACTIONS[beat.id];
    if (action) {
      try { await action(page); } catch (e) { console.error(`   ! ${beat.id}: ${e.message}`); }
    }
    if (STOP_AFTER && beat.id === STOP_AFTER) break;
  }
  const tail = beats[beats.length - 1].end;
  if (!STOP_AFTER) await waitUntil(tail + 1.5);

  fs.writeFileSync(path.join(HERE, 'beat_times.json'), JSON.stringify(times, null, 1), 'utf8');
  const video = page.video();
  await ctx.close();                      // flushes the video file
  const file = video ? await video.path() : null;
  await browser.close();
  console.log('\nvideo:', file);
  console.log('beat_times.json written —', Object.keys(times).length, 'beats');
})().catch((e) => { console.error('ERR', e.stack || e.message); process.exit(1); });
